        b.fangraph_id,
        CASE 
            WHEN l.fangraph_id IS NULL THEN current_timestamp() -- new fangraph id
            WHEN b._row_hash <> l._row_hash THEN current_timestamp() -- existing fangraph id, but changed since yesterday
            ELSE l.fangraph_last_updated_timestamp -- existing fangraph id, has not changed
        END AS fangraph_last_updated_timestamp
    FROM base b
        LEFT JOIN latest_snapshot l
